functions.fs_error:
void fs_error(const char *prefix)
{
    char fmt[256];
    sprintf(fmt, "fs: %s: error", prefix);
    perror(fmt);
}

functions.fs_open:
FILE *fs_open(const char *path, const char *flags)
{
    return fopen(path, flags);
}

functions.fs_rename:
int fs_rename(const char *from, const char *to)
{
    return rename(from, to);
}

functions.fs_stat:
fs_stats *fs_stat(const char *path)
{
    fs_stats *stats = (fs_stats *)malloc(sizeof(fs_stats));
    int e = stat(path, stats);
    if (-1 == e)
    {
        free(stats);
        return ((void *)0);
    }
    return stats;
}

functions.fs_fstat:
fs_stats *fs_fstat(FILE *file)
{
    if (((void *)0) == file)
        return ((void *)0);
    fs_stats *stats = (fs_stats *)malloc(sizeof(fs_stats));
    int fd = fileno(file);
    int e = fstat(fd, stats);
    if (-1 == e)
    {
        free(stats);
        return ((void *)0);
    }
    return stats;
}

functions.fs_lstat:
fs_stats *fs_lstat(const char *path)
{
    fs_stats *stats = (fs_stats *)malloc(sizeof(fs_stats));
    int e = lstat(path, stats);
    if (-1 == e)
    {
        free(stats);
        return ((void *)0);
    }
    return stats;
}

functions.fs_ftruncate:
int fs_ftruncate(FILE *file, int len)
{
    int fd = fileno(file);
    return ftruncate(fd, (off_t)len);
}

functions.fs_truncate:
int fs_truncate(const char *path, int len)
{
    return truncate(path, (off_t)len);
}

functions.fs_chown:
int fs_chown(const char *path, int uid, int gid)
{
    return chown(path, (uid_t)uid, (gid_t)gid);
}

functions.fs_fchown:
int fs_fchown(FILE *file, int uid, int gid)
{
    int fd = fileno(file);
    return fchown(fd, (uid_t)uid, (gid_t)gid);
}

functions.fs_lchown:
int fs_lchown(const char *path, int uid, int gid)
{
    return lchown(path, (uid_t)uid, (gid_t)gid);
}

functions.fs_size:
size_t fs_size(const char *path)
{
    size_t size;
    FILE *file = fs_open(path, "r");
    if (((void *)0) == file)
        return -1;
    fseek(file, 0, 2);
    size = ftell(file);
    fs_close(file);
    return size;
}

functions.fs_fsize:
size_t fs_fsize(FILE *file)
{
    unsigned long pos = ftell(file);
    rewind(file);
    fseek(file, 0, 2);
    size_t size = ftell(file);
    fseek(file, pos, 0);
    return size;
}

functions.fs_read:
char *fs_read(const char *path)
{
    FILE *file = fs_open(path, "r");
    if (((void *)0) == file)
        return ((void *)0);
    char *data = fs_fread(file);
    fclose(file);
    return data;
}

functions.fs_nread:
char *fs_nread(const char *path, int len)
{
    FILE *file = fs_open(path, "r");
    if (((void *)0) == file)
        return ((void *)0);
    char *buffer = fs_fnread(file, len);
    fs_close(file);
    return buffer;
}

functions.fs_fread:
char *fs_fread(FILE *file)
{
    size_t fsize = fs_fsize(file);
    return fs_fnread(file, fsize);
}

functions.fs_fnread:
char *fs_fnread(FILE *file, int len)
{
    char *buffer = (char *)malloc(sizeof(char) * (len + 1));
    size_t n = fread(buffer, 1, len, file);
    buffer[n] = '\0';
    return buffer;
}

functions.fs_write:
int fs_write(const char *path, const char *buffer)
{
    return fs_nwrite(path, buffer, strlen(buffer));
}

functions.fs_nwrite:
int fs_nwrite(const char *path, const char *buffer, int len)
{
    FILE *file = fs_open(path, "w");
    if (((void *)0) == file)
        return -1;
    int result = fs_fnwrite(file, buffer, len);
    fclose(file);
    return result;
}

functions.fs_fwrite:
int fs_fwrite(FILE *file, const char *buffer)
{
    return fs_fnwrite(file, buffer, strlen(buffer));
}

functions.fs_fnwrite:
int fs_fnwrite(FILE *file, const char *buffer, int len)
{
    return (int)fwrite(buffer, 1, len, file);
}

functions.fs_mkdir:
int fs_mkdir(const char *path, int mode)
{
    return mkdir(path, (mode_t)mode);
}

functions.fs_exists:
int fs_exists(const char *path)
{
    struct stat b;
    return stat(path, &b);
}
